export const config = {
  get JIRA_EMAIL() { return process.env.JIRA_EMAIL; },
  set JIRA_EMAIL(val: string | undefined) { process.env.JIRA_EMAIL = val; },
  
  get JIRA_TOKEN() { return process.env.JIRA_TOKEN; },
  set JIRA_TOKEN(val: string | undefined) { process.env.JIRA_TOKEN = val; },
  
  get JIRA_DOMAIN() { return process.env.JIRA_DOMAIN; },
  set JIRA_DOMAIN(val: string | undefined) { process.env.JIRA_DOMAIN = val; },
  
  get JIRA_PROJECT() { return process.env.JIRA_PROJECT; },
  set JIRA_PROJECT(val: string | undefined) { process.env.JIRA_PROJECT = val; },
  
  get missing() {
    return ["JIRA_EMAIL", "JIRA_TOKEN", "JIRA_DOMAIN", "JIRA_PROJECT"].filter(
      (k) => !process.env[k]
    );
  }
};
